    assert!(outcome.messages().iter().any(|message| message.code.0 == CODE_INVARIANT), "got {:?}", outcome.messages());
    assert_eq!(resolve(&snapshot.value, &key("title")), Some(&JsonValue::String { value: "hexagonal cut".to_string() }));
}

